<?php
/**
 * Shared content for the Cortex add-on pages (/cortex/<slug>/): Production, Project Management, HR & Payroll, POS,
 * Property Management, Assets Management. Each page file returns cortex_addon_page('<slug>').
 * Features were written from the product names and still need DWP confirmation (CONFIRM.md).
 * Page structure: product_hero (laptop with the app screen), then either the production process and live control room
 * (prod_process + prod_control, Production) or the features grid (sap_modules), then FAQ and cta_band.
 */
if (!function_exists('cortex_extra')) {
/** Outcomes and integrations sections for a Cortex add-on (content/cortex-addons-extra.php), ready to insert in a page. */
function cortex_extra(string $slug, string $lang, string $logo, bool $noSap = false): array
{
    static $x = null;
    $x ??= (static fn() => include __DIR__ . '/cortex-addons-extra.php')();
    $e = $x[$slug][$lang] ?? null;
    if (!$e) return ['outcomes' => [], 'integrations' => []];
    return [
        'outcomes' => [['type' => 'outcomes', 'id' => 'results'] + $e['outcomes']],
        'integrations' => [['type' => 'integrations', 'id' => 'integrations', 'logo' => $logo] + ($noSap ? ['no_sap' => true] : []) + $e['integrations']],
    ];
}
}
